<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { workspaceAi } from '../aiWorkspace';
import { aiFailureMessage } from '../lib/ai';
const tino=computed(()=>workspaceAi.style==='TINO');
const panel=ref<HTMLElement>();
watch(()=>workspaceAi.busy,async busy=>{
  if(!busy||!window.matchMedia('(max-width:760px)').matches)return;
  await nextTick();
  panel.value?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});
});
</script>
<template><section v-if="workspaceAi.active" id="sidebar-ai" ref="panel" class="sidebar-ai" aria-label="AI 排错对话框"><header><span>{{tino?'小侦探Tino':'AI 排错指导'}}</span><span v-if="workspaceAi.busy" class="thinking-dot" aria-hidden="true"/></header><div class="ai-dialogue" tabindex="0" aria-label="AI 指导内容" aria-live="polite"><p v-if="workspaceAi.contextError" class="ai-failure" role="alert">{{workspaceAi.contextError}}</p><p v-else-if="!workspaceAi.ready" class="ai-idle">正在读取作业设置…</p><p v-else-if="!workspaceAi.problemTitle" class="ai-idle">选择题目后，可在这里查看 AI 排错指导。</p><p v-else-if="!workspaceAi.enabled" class="ai-idle">教师未开放本作业的 AI 辅助。</p><p v-else-if="workspaceAi.busy" class="ai-idle" role="status">正在分析当前代码…</p><p v-else-if="workspaceAi.error" class="ai-failure" role="alert">{{workspaceAi.error}}</p><p v-else-if="workspaceAi.analysis?.status==='FAILED'" class="ai-failure" role="alert">{{aiFailureMessage(workspaceAi.analysis.errorCode)}}</p><template v-else-if="workspaceAi.analysis?.status==='COMPLETED'"><p>{{workspaceAi.analysis.summary}}</p><article v-for="(finding,index) in workspaceAi.analysis.findings" :key="index"><small>{{finding.category}}<template v-if="finding.startLine!==null"> · 第 {{finding.startLine}} 行</template></small><p>{{finding.reason}}</p><p class="ai-hint">{{finding.hint}}</p></article></template><p v-else class="ai-idle">尚无指导内容。请先分析当前代码。</p><p v-if="workspaceAi.codeChanged && (workspaceAi.analysis||workspaceAi.busy)" class="snapshot-note">代码已修改，当前指导对应上次发送的代码。</p></div><div v-if="tino" class="tino-stage"><div class="tino-sprite" role="img" aria-label="带着放大镜的小侦探 Tino"/></div></section></template>
<style scoped>
.sidebar-ai{display:flex;flex:1;min-height:150px;flex-direction:column;margin:22px 8px 12px;overflow:hidden}.sidebar-ai header{display:flex;align-items:center;justify-content:space-between;color:#d4ecea;font-size:12px;padding:0 1px 10px}.ai-dialogue{position:relative;overflow:auto;min-height:80px;background:#1c414d;border:1px solid #315967;border-radius:11px;padding:12px 14px;scrollbar-width:thin;scrollbar-color:#466975 transparent;color:#e0efee;font-size:12px;line-height:1.8;flex:1}.ai-dialogue p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.ai-dialogue article{border-top:1px solid #3b5c66;margin-top:12px;padding-top:12px}.ai-dialogue article small{color:#86c4c0;font-size:10px}.ai-dialogue article p{margin-top:5px}.ai-dialogue .ai-hint{color:#bfe2d8}.ai-dialogue .ai-idle{color:#a1bfca}.ai-dialogue .ai-failure{color:#ffbfaf}.ai-dialogue .snapshot-note{color:#d7c6a0;font-size:10px;margin-top:12px}.tino-stage{display:flex;justify-content:center;flex-shrink:0;padding-top:8px}.tino-sprite{width:96px;height:104px;background-image:url('../assets/tino-spritesheet.png');background-size:768px 1144px;background-repeat:no-repeat;animation:tino-idle 2.4s steps(6) infinite}.thinking-dot{width:6px;height:6px;border-radius:50%;background:#6fc3b5;animation:thinking 1s ease-in-out infinite alternate}@keyframes tino-idle{to{background-position:-576px 0}}@keyframes thinking{to{opacity:.3}}@media(prefers-reduced-motion:reduce){.tino-sprite,.thinking-dot{animation:none}}
</style>
